package br.com.fastfps.chunk; public final class ChunkRegionCache{private final int n;private final int[] data;public ChunkRegionCache(int radius){n=Math.max(1,radius)*2+1;data=new int[n*n*n];}private int i(int x,int y,int z){return(y*n+z)*n+x;}public int get(int x,int y,int z){return x<0||y<0||z<0||x>=n||y>=n||z>=n?0:data[i(x,y,z)];}public void set(int x,int y,int z,int v){if(x>=0&&y>=0&&z>=0&&x<n&&y<n&&z<n)data[i(x,y,z)]=v;}}
